mapper.select:
SELECT user_id AS userId, phone, nickname, activity_level_tag AS activityLevelTag, intention_tag AS intentionTag, value_level_tag AS valueLevelTag, payment_behavior_tag AS paymentBehaviorTag, browse_cnt_30d AS browseCnt30d, appointment_cnt_30d AS appointmentCnt30d, rent_amount AS rentAmount, data_date AS dataDate FROM tenant_profile_features
AND phone LIKE CONCAT('%', #{queryVo.phone}, '%')
AND nickname LIKE CONCAT('%', #{queryVo.nickname}, '%')
AND activity_level_tag = #{queryVo.activityLevelTag}
AND intention_tag = #{queryVo.intentionTag}
AND value_level_tag = #{queryVo.valueLevelTag}
AND payment_behavior_tag = #{queryVo.paymentBehaviorTag}
AND data_date >= #{queryVo.dataDateStart}
AND data_date <= #{queryVo.dataDateEnd}
ORDER BY data_date DESC, user_id ASC
